thm-hyp(
    list-partial(
        Type.annotation(@x, X@Topology.ctxt.X),
        Type.annotation(@x_0, X@Topology.ctxt.X),
        Type.annotation(@y, Y@Topology.ctxt.Y)
    ),
    Logic.iff(
        Topology.mapLimit(x, x_0, f, y),
        Logic.forall-typed(
            @x_n,
            Type.to(Nat, X@Topology.ctxt.X),
            Logic.implies(Topology.seqConvergence(x_n, x), Topology.seqConvergence(Type.apply(f, x_n), y))
        )
    )
)
